/**
 * Europe: the 37 countries our 101 pre-built European towns sit in.
 *
 * Every record was checked on 21 October 2026 against the organisation's own
 * pages (each URL in `links` fetched and read) and a second source: a public
 * register (the Charity Commission for England and Wales via its register and
 * the findthatcharity.uk mirror of it, OSCR, the Charity Commission for
 * Northern Ireland, the Irish Charities Regulator, the French RNA or a decree
 * of "utilité publique", Spain's Registro Nacional de Asociaciones, Italy's
 * RUNTS, the German Vereinsregister as the Impressum cites it, the Dutch KVK
 * number, the Nordic organisation registers, Poland's KRS, Czechia's ARES…)
 * or a network's own member list (the BirdLife partner list, The Rivers
 * Trust's member trusts, the Wildlife Trusts, the Fédération des Conservatoires
 * d'espaces naturels). A `//` note above a record says when a legitimate
 * organisation has no findable register entry, or when its site refuses plain
 * GETs and was read in a browser-grade fetch instead. Public bodies carry
 * `kind: "agency"` and no registry.
 *
 * Groups: one `//` heading per country, the United Kingdom first, then
 * Ireland, then the continent west to east, then the Europe-wide networks.
 * Europe has no `admin1Code` in our place data, so regional bodies are placed
 * by `radius` or `box`. `waters` are spelled as the fishing pages spell the
 * OpenStreetMap names ("River Thames", "River Ness", "La Loire", "L'Ill").
 */
import type { Organisation } from "./types";

const V = "2026-10-21";
const CC = (id: string) => ({ body: "Charity Commission", id, url: `https://register-of-charities.charitycommission.gov.uk/charity-search/-/charity-details/${id}` });
const OSCR = (id: string) => ({ body: "OSCR", id, url: `https://www.oscr.org.uk/about-charities/search-the-register/charity-details?number=${id}` });
const FTC = (orgid: string) => `https://findthatcharity.uk/orgid/${orgid}`;
const BIRDLIFE_LIST = "https://en.wikipedia.org/wiki/List_of_BirdLife_International_national_partner_organisations";
const RIVERS_TRUST_LIST = "https://en.wikipedia.org/wiki/The_Rivers_Trust";

const LPO_LOCALES = "https://www.lpo.fr/qui-sommes-nous/lpo-locales/annuaire-web";
const FNPF_DIR = "https://www.federationpeche.fr/116-fd.htm";
const CEN_DIR = (s: string) => `https://reseau-cen.org/annuaire/conservatoire-despaces-naturels-${s}/`;
const V2 = "2026-10-22";
/** BirdLife's own list of its European and Central Asian partners, each linked to its partner page. */
const BL_ECA = "https://www.birdlife.org/europe-and-central-asia/our-partners/";
const BL = (s: string) => `https://www.birdlife.org/partners/${s}/`;
/** The Jane Goodall Institute's global site, whose footer lists every national institute and Roots & Shoots office. */
const JGI_GLOBAL = "https://janegoodall.global/";
/** Poland's National Court Register (KRS): the Ministry of Justice's public API returns the current extract for each number. */
const KRS = (nr: string) => ({ body: "Krajowy Rejestr Sądowy (KRS)", id: nr, url: `https://api-krs.ms.gov.pl/api/krs/OdpisAktualny/${nr}?rejestr=S&format=json` });
/** Czechia's ARES register of economic subjects: one REST record per IČO. */
const ARES = (ico: string) => ({ body: "ARES (Czech register of economic subjects)", id: `IČO ${ico}`, url: `https://ares.gov.cz/ekonomicke-subjekty-v-be/rest/ekonomicke-subjekty/${ico}` });
/** Norway's Brønnøysund Register Centre (Enhetsregisteret): one public page per organisation number. */
const BRREG = (orgnr: string) => ({ body: "Brønnøysundregistrene (Enhetsregisteret)", id: orgnr, url: `https://virksomhet.brreg.no/nb/oppslag/enheter/${orgnr}` });
/** Estonia's e-Business Register (e-Äriregister) entry by registry code. */
const RIK = (code: string) => ({ body: "e-Äriregister (Estonian Centre of Registers and Information Systems)", id: code, url: `https://ariregister.rik.ee/eng/company/${code}` });
const LPO_RUP = { body: "Journal officiel (décret de reconnaissance d'utilité publique)", id: "LPO France, décret du 3 juillet 1986", url: "https://www.lpo.fr/qui-sommes-nous/lpo-france" };

/**
 * An LPO regional body: either an independent "LPO locale" (an association
 * loi 1901 under convention with LPO France, with its own site) or a territorial
 * delegation of LPO France whose pages live on lpo.fr. Both run the outings,
 * counts, rescue networks and Refuges LPO for their region.
 */
const lpoRegion = (o: {
  slug: string;
  name: string;
  shortName: string;
  home: string;
  area: Organisation["areas"][number];
  blurb: string;
  asks: string[];
  programme?: boolean;
  links?: Partial<Organisation["links"]>;
  places?: string[];
  waters?: string[];
  sources?: string[];
}): Organisation => ({
  slug: o.slug,
  name: o.name,
  shortName: o.shortName,
  network: "BirdLife International",
  scope: "regional",
  continent: "europe",
  countryCode: "FR",
  topics: ["birds", "wildlife", "youth"],
  areas: [o.area],
  waters: o.waters,
  blurb: o.blurb,
  asks: o.asks,
  links: { home: o.home, ...o.links },
  registry: o.programme ? LPO_RUP : undefined,
  kind: o.programme ? "programme" : "charity",
  places: o.places,
  verified: V,
  sources: [o.home, ...(o.sources ?? []), LPO_LOCALES],
});

